#if !FLUIDCACHING_COMPILE
// <autogenerated />
#pragma warning disable
#endif

#nullable enable

using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Linq;
using System.Threading.Tasks;

namespace FluidCaching;

/// <summary>
/// Provides dictionary key / value access to any object in the cache.
/// </summary>
#if !FLUIDCACHING_COMPILE
[global::Microsoft.CodeAnalysis.Embedded]
[global::System.Diagnostics.DebuggerNonUserCode]
#endif
internal sealed class Index<TKey, T> : IIndex<TKey, T>, IIndexManagement<T>
    where T : class
    where TKey : notnull
{
    private readonly FluidCache<T> owner;
    private readonly LifespanManager<T> lifespanManager;
    private readonly GetKey<T, TKey> getKey;
    private readonly ItemCreator<TKey, T>? loadItem;
    private readonly IEqualityComparer<TKey>? keyEqualityComparer;

    private readonly object syncObject = new();

    private Dictionary<TKey, WeakReference<Node<T>>> index = new();

    /// <summary>
    /// Initializes a new instance of the <see cref="Index{TKey, T}"/> class.
    /// </summary>
    /// <param name="owner">The parent of the index.</param>
    /// <param name="lifespanManager">The object that tracks the age of all cached items.</param>
    /// <param name="getKey">Delegate to get the key from an object.</param>
    /// <param name="loadItem">Delegate to load an object if it is not found in the index.</param>
    /// <param name="keyEqualityComparer">The equality comparer to be used to compare the keys. Optional.</param>
    public Index(
        FluidCache<T> owner,
        LifespanManager<T> lifespanManager,
        GetKey<T, TKey> getKey,
        ItemCreator<TKey, T>? loadItem,
        IEqualityComparer<TKey>? keyEqualityComparer)
    {
        this.owner = owner;
        this.lifespanManager = lifespanManager;
        this.getKey = getKey;
        this.loadItem = loadItem;
        this.keyEqualityComparer = keyEqualityComparer;
        RebuildIndex();
    }

    [SuppressMessage("Design", "AV1554:Do not use optional parameters in interface methods or their concrete implementations",
        Justification = "Part of the existing public API")]
    public async Task<T?> GetItem(TKey key, ItemCreator<TKey, T>? createItem = null)
    {
        T? value = null;

        lock (syncObject)
        {
            Node<T>? node = FindExistingNodeByKey(key);
            if (node is not null)
            {
                value = node.Value;

                node.Touch();
            }
        }

        if (value is null)
        {
            value = await TryCreate(key, createItem).ConfigureAwait(false);
            if (value is not null)
            {
                Node<T>? newOrExistingNode = owner.TryAddAsNode(value);

                // The node can be removed by a concurrent clean-up, so fall back to the value we just created
                value = newOrExistingNode?.Value ?? value;

                lifespanManager.CheckValidity();
            }
        }

        return value;
    }

    private async Task<T?> TryCreate(TKey key, ItemCreator<TKey, T>? createItem)
    {
        ItemCreator<TKey, T>? creator = createItem ?? loadItem;
        if (creator is not null)
        {
            Task<T>? task = creator(key);
            if (task is null)
            {
                throw new ArgumentNullException(nameof(createItem),
                    "Expected a non-null Task. Did you intend to return a null-returning Task instead?");
            }

            return await task.ConfigureAwait(false);
        }

        return null;
    }

    /// <summary>
    /// Deletes the object that matches <paramref name="key"/> from the cache.
    /// </summary>
    public void Remove(TKey key)
    {
        Node<T>? node = FindExistingNodeByKey(key);
        if (node is not null)
        {
            lock (syncObject)
            {
                node = FindExistingNodeByKey(key);
                if (node is not null)
                {
                    node.RemoveFromCache();

                    lifespanManager.CheckValidity();
                }
            }
        }
    }

    /// <summary>
    /// Tries to find this item in the index and returns its node.
    /// </summary>
    public Node<T>? FindItem(T item)
    {
        return FindExistingNodeByKey(getKey(item));
    }

    private Node<T>? FindExistingNodeByKey(TKey key)
    {
        // NOTE: This is called both with and without holding the lock, which is how the cache has always worked.
        // ReSharper disable once InconsistentlySynchronizedField
        if (index.TryGetValue(key, out WeakReference<Node<T>>? reference) && reference.TryGetTarget(out Node<T>? node))
        {
            lifespanManager.Stats.RegisterHit();
            return node;
        }

        return null;
    }

    /// <summary>
    /// Removes all items from the index.
    /// </summary>
    public void ClearIndex()
    {
        lock (syncObject)
        {
            index.Clear();
        }
    }

    /// <summary>
    /// Adds a new item to the index.
    /// </summary>
    /// <param name="item">The item to add.</param>
    /// <returns>
    /// Returns <see langword="true"/> if the item could be added to the index, or <see langword="false"/> otherwise.
    /// </returns>
    public bool AddItem(Node<T> item)
    {
        lock (syncObject)
        {
            T? value = item.Value;
            if (value is null)
            {
                return false;
            }

            TKey key = getKey(value);

            if (!index.TryGetValue(key, out WeakReference<Node<T>>? reference) ||
                !reference.TryGetTarget(out Node<T>? node) ||
                node.Value is null)
            {
                index[key] = new WeakReference<Node<T>>(item, trackResurrection: false);
                return true;
            }

            return false;
        }
    }

    /// <summary>
    /// Removes all items from the index and reloads each item (this gets rid of dead nodes).
    /// </summary>
    public int RebuildIndex()
    {
        lock (syncObject)
        {
            // Create a new dictionary, this way there is no need for locking the index itself
            Dictionary<TKey, WeakReference<Node<T>>> keyValues = lifespanManager
                .Where(node => node.Value is not null)
                .ToDictionary(node => getKey(node.Value!), node => new WeakReference<Node<T>>(node));

            index = new Dictionary<TKey, WeakReference<Node<T>>>(keyValues, keyEqualityComparer);
            return index.Count;
        }
    }
}
